<?php
require_once __DIR__ . '/../includes/auth.php'; require_login(); $active_menu='reports';$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$where=["p.payment_status IN ('Paid','Partially Paid')"];$params=[];if(is_valid_date($from)){$where[]='p.payment_date>=:from';$params[':from']=$from;}if(is_valid_date($to)){$where[]='p.payment_date<=:to';$params[':to']=$to;}$sql="SELECT p.*,a.service_price,CONCAT(c.first_name,' ',c.last_name) customer_name,s.service_name FROM payments p JOIN appointments a ON a.appointment_id=p.appointment_id JOIN customers c ON c.customer_id=a.customer_id JOIN services s ON s.service_id=a.service_id WHERE ".implode(' AND ',$where);$rows=all_rows($sql.' ORDER BY p.payment_date DESC,p.payment_id DESC',$params);$total=array_sum(array_map(static fn($row)=>(float)$row['amount'],$rows));$page_title='Revenue Report';require __DIR__.'/../includes/header.php';
?>
<h2 class="print-heading">Revenue Report</h2><?php require __DIR__.'/../includes/report_nav.php';?><form method="get" class="row g-2 align-items-end no-print mb-3"><div class="col-sm-4"><label class="form-label">From date</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-sm-4"><label class="form-label">To date</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-sm-4"><button class="btn btn-primary">Apply date range</button> <a class="btn btn-outline-secondary" href="<?=e(app_url('reports/revenue.php'))?>">Clear</a></div></form><div class="card shadow-sm table-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Payment ID</th><th>Appointment</th><th>Customer</th><th>Amount</th><th>Method</th><th>Payment date</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center py-4 text-secondary">No revenue records match the selected dates.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td>#<?= (int)$row['payment_id']?></td><td>#<?= (int)$row['appointment_id']?> · <?=e($row['service_name'])?></td><td><?=e($row['customer_name'])?></td><td><?=money($row['amount'])?></td><td><?=e($row['payment_method'])?></td><td><?=e($row['payment_date'])?></td><td><?=status_badge($row['payment_status'])?></td></tr><?php endforeach;?></tbody><tfoot><tr class="table-light"><th colspan="3" class="text-end">Total revenue received</th><th><?=money($total)?></th><th colspan="3"></th></tr></tfoot></table></div></div><?php require __DIR__.'/../includes/footer.php';
